import{_ as t,o as i,c as e,a3 as s}from"./chunks/framework.CWYzGJW1.js";const c=JSON.parse('{"title":"O1 備份與還原","description":"要備份的是「資料與設定」, 不是模型檔. 對話資料庫, 向量庫, 設定檔與測試集要定期備份, 並至少一份存放在另一台裝置; 備份沒有還原過, 就不算備份 (信心: 高, 屬通用做法).","frontmatter":{"description":"要備份的是「資料與設定」, 不是模型檔. 對話資料庫, 向量庫, 設定檔與測試集要定期備份, 並至少一份存放在另一台裝置; 備份沒有還原過, 就不算備份 (信心: 高, 屬通用做法)."},"headers":[],"relativePath":"ops/backup.md","filePath":"ops/backup.md","lastUpdated":1793064260000}'),d={name:"ops/backup.md"};function r(l,a,n,o,h,p){return i(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="o1-備份與還原" tabindex="-1">O1 備份與還原 <a class="header-anchor" href="#o1-備份與還原" aria-label="Permalink to &quot;O1 備份與還原&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀</li><li>資料基準日: 2026-10-27</li><li>實機驗證: 未進行 (備份範本為整理者依 Docker 文件 Volumes 頁面改寫)</li></ul></div><p><strong>結論</strong>: 要備份的是「資料與設定」, 不是模型檔. 對話資料庫, 向量庫, 設定檔與測試集要定期備份, 並至少一份存放在另一台裝置; 備份沒有還原過, 就不算備份 (信心: 高, 屬通用做法). 頻率建議每週一次 (推論, 信心: 低; 依資料變動量調整).</p><h2 id="o1-1-備份範圍" tabindex="-1">O1.1 備份範圍 <a class="header-anchor" href="#o1-1-備份範圍" aria-label="Permalink to &quot;O1.1 備份範圍&quot;">​</a></h2><p>取捨的原則是: 重新下載就能取回的東西不必備份, 只存在自己這裡的資料一定要備份. 表中的資料卷 (volume) 是容器用來長期保存資料的儲存空間; 向量庫存放文件段落轉成的數字, 供檢索時依意思找出相關段落.</p><table tabindex="0"><thead><tr><th>對象</th><th>是否備份</th><th>說明</th></tr></thead><tbody><tr><td>介面的資料卷 (對話, 使用者, 設定)</td><td>是</td><td>以 Open WebUI 為例, 資料存放在掛載到 <code>/app/backend/data</code> 的資料卷 (來源: Open WebUI Quick Start)</td></tr><tr><td>向量庫資料</td><td>是</td><td>重建需要重新嵌入全部文件, 耗時又耗算力. Open WebUI 的資料目錄內含 <code>vector_db/</code> (ChromaDB), 隨資料卷一併備份 (來源: Open WebUI 文件 Backups)</td></tr><tr><td>原始文件</td><td>是</td><td>向量庫只是衍生資料, 原始文件才是來源</td></tr><tr><td>設定檔 (compose 檔, 閘道設定)</td><td>是</td><td>納入版本控制</td></tr><tr><td><code>.env</code> 與金鑰</td><td>是, 但分開存放</td><td>與一般備份分開, 限制存取, 不放進同一個備份包</td></tr><tr><td>測試集 (<a href="/lanai-handbook/build/m6-observability">M6</a>)</td><td>是</td><td>回歸測試的依據</td></tr><tr><td>版本紀錄 (<a href="/lanai-handbook/ops/versioning">O2</a>)</td><td>是</td><td>還原時要知道當時的版本</td></tr><tr><td>Modelfile 與自訂腳本</td><td>是</td><td>體積小, 重建困難</td></tr><tr><td>模型檔</td><td>否</td><td>可重新下載; 但要記錄來源與 revision (<a href="/lanai-handbook/build/m1-inference">M1.5 節</a>)</td></tr></tbody></table><h2 id="o1-2-備份做法" tabindex="-1">O1.2 備份做法 <a class="header-anchor" href="#o1-2-備份做法" aria-label="Permalink to &quot;O1.2 備份做法&quot;">​</a></h2><p>原則 (信心: 高, 屬通用做法): 備份前先停止會寫入資料的服務, 以免資料庫檔案處於不一致狀態; 備份檔存放到另一台裝置或另一個磁碟, 並保留多個日期的版本. Open WebUI 文件也建議在冷檔案系統上備份資料庫 (停止服務後備份), 且不要依賴管理介面的資料庫下載功能, 因為它可能漏掉尚在 <code>webui.db-wal</code> 的新寫入 (來源: Open WebUI 文件 Backups).</p><p>下列範本的三行指令依序是: 停止服務, 用一個暫時的小容器把資料卷打包成壓縮檔, 再重新啟動服務.</p><p><strong>Docker 資料卷的備份範本</strong> (整理者依 Docker 文件 Volumes 頁面的 <code>tar</code> 備份做法改寫, 未實機驗證, 執行前請對照該頁; 映像請固定版本標籤):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> open-webui</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> open-webui:/data</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;:/backup</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> alpine:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">固定版</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">本</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">  tar</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> czf</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> /backup/open-webui-</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> +%F</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> /data</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> open-webui</span></span></code></pre></div><p><strong>備份後立即檢查</strong>:</p><ul><li>[ ] 備份檔大小合理 (不是 0 或異常偏小)</li><li>[ ] 可列出內容: <code>tar tzf &lt;備份檔&gt; | head</code></li><li>[ ] 已複製到另一台裝置或另一個磁碟</li><li>[ ] 記錄備份日期與來源版本</li></ul><p>Open WebUI 官方建議每次更新前先備份資料卷 (來源: Open WebUI Quick Start 與 Updating 文件), 因此升級流程應把備份放在第一步 (<a href="/lanai-handbook/ops/versioning">O2</a>).</p><h2 id="o1-3-還原演練" tabindex="-1">O1.3 還原演練 <a class="header-anchor" href="#o1-3-還原演練" aria-label="Permalink to &quot;O1.3 還原演練&quot;">​</a></h2><p>沒有演練過的備份, 無法確定能用. 還原演練可以想成消防演練: 平常走過一遍, 真正需要時才知道每一步做得到. 演練時不要動正式環境:</p><ol><li>用不同的容器名稱, 資料卷名稱與連接埠 (例如 <code>127.0.0.1:3001</code>) 啟動一份新的介面.</li><li>把備份檔解開到新的資料卷.</li><li>登入並確認: 帳號存在, 舊對話可開啟, 檢索資料可查詢.</li><li>記錄耗時與遇到的問題, 更新還原步驟.</li><li>刪除演練用的容器與資料卷.</li></ol><p>建議每季演練一次, 且在大版本升級前加做一次 (頻率為建議值, 屬推論, 信心: 低).</p><p>還原到正式環境時, 先保留現有資料卷, 不直接覆蓋, 確認新環境正常後再清理舊資料.</p><h2 id="o1-4-定期檢查表" tabindex="-1">O1.4 定期檢查表 <a class="header-anchor" href="#o1-4-定期檢查表" aria-label="Permalink to &quot;O1.4 定期檢查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>頻率</th><th>工作</th></tr></thead><tbody><tr><td>每週</td><td>執行備份並檢查; 檢查安全公告 (<a href="/lanai-handbook/ops/advisories">O3</a>)</td></tr><tr><td>每月</td><td>比對 CISA KEV 清單; 評估是否有版本需升級; 檢視備份保留份數與磁碟空間</td></tr><tr><td>每季</td><td>還原演練; 檢視帳號清單; 檢視金鑰存放位置</td></tr><tr><td>升級前</td><td>先做一次備份, 並確認該備份可還原</td></tr></tbody></table><h2 id="o1-5-備份本身的安全" tabindex="-1">O1.5 備份本身的安全 <a class="header-anchor" href="#o1-5-備份本身的安全" aria-label="Permalink to &quot;O1.5 備份本身的安全&quot;">​</a></h2><p>備份檔含有對話內容與使用者資料, 與正式環境同樣敏感 (信心: 高). 存放備份的裝置要有存取控制; 若備份離開機房或放到雲端, 先加密, 並決定金鑰由誰保管.</p><p>美國 CISA 的勒索軟體指南建議三件事: 為關鍵資料保留離線且加密的備份; 備份要離線保存, 因為許多勒索軟體會先找出能存取的備份並刪除或加密; 定期在災難復原情境中測試備份的可用性與完整性 (來源: CISA #StopRansomware Guide). 對手冊讀者, 「離線」可以是平常不接在網路上的外接硬碟. 指南沒有規定加密金鑰怎麼保管, 建議金鑰不要和備份檔放在同一個裝置, 並另外記錄在密碼管理工具或紙本保管處 (整理者建議, 信心: 中).</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><ul><li><a href="https://docs.openwebui.com/getting-started/quick-start/" target="_blank" rel="noreferrer">Open WebUI 文件: Quick Start (資料卷 <code>/app/backend/data</code>, 更新前備份)</a></li><li><a href="https://docs.openwebui.com/getting-started/updating/" target="_blank" rel="noreferrer">Open WebUI 文件: Updating (更新前備份, 還原會先清空資料卷)</a></li><li><a href="https://docs.openwebui.com/tutorials/maintenance/backups/" target="_blank" rel="noreferrer">Open WebUI 文件: Backups (備份範圍, 冷備份建議)</a></li><li><a href="https://docs.docker.com/engine/storage/volumes.md" target="_blank" rel="noreferrer">Docker 文件: Volumes (Back up a volume, Restore volume from a backup)</a></li><li><a href="https://www.cisa.gov/stopransomware/ransomware-guide" target="_blank" rel="noreferrer">CISA: #StopRansomware Guide (離線加密備份, 定期測試備份)</a></li><li>手冊內部連結: <a href="/lanai-handbook/build/m1-inference">M1.5 節</a>, <a href="/lanai-handbook/build/m6-observability">M6</a>, <a href="/lanai-handbook/ops/versioning">O2</a>, <a href="/lanai-handbook/ops/advisories">O3</a></li></ul><p>整理者建議 (推論, 無外部來源): O1.1 的備份對象取捨 (模型檔不備份, <code>.env</code> 分開存放), O1.3 的還原演練步驟與「每季一次」的頻率 (本文已標信心: 低), O1.4 的定期檢查表, O1.5 的存取控制原則與金鑰保管建議 (加密與離線備份的依據為 CISA 指南). 備份檔大小檢查與 <code>tar tzf</code> 列出內容屬通用做法, 未另引來源.</p><p>文中的類比 (消防演練): 整理者所寫, 無外部來源, 不應當作技術定義引用.</p>`,28)])])}const b=t(d,[["render",r]]);export{c as __pageData,b as default};
